import {defineComponent,h,ref} from 'vue';
import {safeFilename} from '../../shared/safety.js';
export const YkAIArtifact=defineComponent({name:'YkAIArtifact',props:{title:{type:String,default:'设计产物'},content:{type:String,default:''},summary:{type:String,default:'生成的内容仅供审阅，应用前请检查。'},language:{type:String,default:'text'},downloadable:{type:Boolean,default:true}},emits:['download','copy'],setup(p,{emit}){const tab=ref('content'),feedback=ref('');async function copy(){try{await navigator.clipboard.writeText(p.content);feedback.value='已复制';emit('copy',{ok:true});}catch{feedback.value='请选中文本复制';emit('copy',{ok:false});}}
 function download(){const url=URL.createObjectURL(new Blob([p.content],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=safeFilename(p.title);a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);emit('download');}
 return()=>h('section',{class:'yk-ai-artifact'},[h('header',{},[h('div',{},[h('span',{class:'yk-ai-artifact__kicker'},'ARTIFACT / '+p.language),h('h3',{},p.title)]),h('div',{class:'yk-ai-artifact__actions'},[h('button',{type:'button',onClick:copy},'复制'),p.downloadable?h('button',{type:'button',onClick:download},'导出文本'):null])]),h('div',{class:'yk-ai-artifact__tabs',role:'group','aria-label':'产物视图'},[['content','内容'],['summary','说明']].map(([value,label])=>h('button',{type:'button','aria-pressed':tab.value===value,onClick:()=>tab.value=value},label))),tab.value==='content'?h('pre',{},h('code',{},p.content)):h('p',{class:'yk-ai-artifact__summary'},p.summary),feedback.value?h('small',{role:'status'},feedback.value):null,h('footer',{},'安全文本预览 · 不执行 HTML / JavaScript')]);
}});
